insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$01-hauptpflichten-535#1$t$,
  $t$01-hauptpflichten-535$t$,
  $t$Hauptpflichten von Vermieter und Mieter (§ 535 BGB)$t$,
  $t$Pflichten des Mieters$t$,
  '{"pflichten","miete","gebrauchsueberlassung","instandhaltung"}',
  $t$Nach § 535 Abs. 2 BGB ist der Mieter verpflichtet, die **vereinbarte Miete zu entrichten**.
Nebenpflichten sind die pflegliche Behandlung der Wohnung, die Anzeige von Mängeln
(§ 536c BGB), die Duldung erforderlicher Erhaltungsmaßnahmen (§ 555a BGB) und die Rückgabe
der Wohnung bei Vertragsende (§ 546 BGB).

## Musterformulierung
„Der Vermieter überlässt dem Mieter die im Mietvertrag bezeichnete Wohnung zum Gebrauch
als Wohnraum und erhält sie während der Mietzeit in vertragsgemäßem Zustand. Der Mieter
zahlt die vereinbarte Miete und behandelt die Mietsache pfleglich."$t$,
