insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$03-kaution-551#2$t$,
  $t$03-kaution-551$t$,
  $t$Mietsicherheit / Kaution (§ 551 BGB)$t$,
  $t$Musterformulierung$t$,
  '{"kaution","sicherheit","deposit","anlage","ratenzahlung"}',
  $t$„Der Mieter leistet eine Kaution in Höhe von zwei Nettokaltmieten [Betrag]. Sie kann in
drei gleichen Monatsraten gezahlt werden; die erste Rate ist zu Mietbeginn fällig. Der
Vermieter legt die Kaution getrennt von seinem Vermögen zum üblichen Sparzinssatz an; die
Zinsen stehen dem Mieter zu (§ 551 BGB)."$t$,
