insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$04-betriebskosten-556-betrkv#0$t$,
  $t$04-betriebskosten-556-betrkv$t$,
  $t$Betriebskosten und Abrechnung (§ 556 BGB, BetrKV)$t$,
  $t$Umlage nur bei Vereinbarung$t$,
  '{"betriebskosten","nebenkosten","abrechnung","betrkv","vorauszahlung"}',
  $t$Betriebskosten trägt im Zweifel der Vermieter. Sie können nur auf den Mieter umgelegt
werden, wenn dies **vereinbart** ist (§ 556 Abs. 1 BGB). Üblich ist die Formel „Der Mieter
trägt die Betriebskosten im Sinne des § 556 BGB i. V. m. § 2 BetrKV" nebst Verweis auf die
beigefügte Aufstellung. Vereinbart werden können eine **Vorauszahlung** (mit jährlicher
Abrechnung) oder eine **Pauschale** (ohne Abrechnung).$t$,
