insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$04-betriebskosten-556-betrkv#2$t$,
  $t$04-betriebskosten-556-betrkv$t$,
  $t$Betriebskosten und Abrechnung (§ 556 BGB, BetrKV)$t$,
  $t$Abrechnungsfrist (§ 556 Abs. 3 BGB)$t$,
  '{"betriebskosten","nebenkosten","abrechnung","betrkv","vorauszahlung"}',
  $t$Über Vorauszahlungen ist **jährlich abzurechnen**. Die Abrechnung muss dem Mieter
**spätestens zwölf Monate nach Ende des Abrechnungszeitraums** zugehen. Danach kann der
Vermieter **keine Nachforderung** mehr geltend machen, es sei denn, er hat die Verspätung
nicht zu vertreten. Einwendungen des Mieters gegen die Abrechnung sind ihm **binnen zwölf
Monaten nach Zugang** mitzuteilen.

## Anpassung der Vorauszahlungen
Nach einer Abrechnung darf jede Vertragspartei die Vorauszahlungen durch Erklärung in
Textform auf eine **angemessene Höhe** anpassen (§ 560 Abs. 4 BGB).$t$,
