insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$05-mieterhoehung-vergleichsmiete-558#1$t$,
  $t$05-mieterhoehung-vergleichsmiete-558$t$,
  $t$Mieterhöhung bis zur ortsüblichen Vergleichsmiete (§ 558 BGB)$t$,
  $t$Begründung (§ 558a BGB)$t$,
  '{"mieterhoehung","vergleichsmiete","kappungsgrenze","mietspiegel"}',
  $t$Das Verlangen ist in Textform zu stellen und zu begründen, insbesondere durch Bezugnahme
auf einen **Mietspiegel**, ein Sachverständigengutachten oder die Benennung von
**mindestens drei vergleichbaren Wohnungen**. Existiert ein qualifizierter Mietspiegel, so
sind dessen Werte auch bei anderer Begründung mitzuteilen.

## Zustimmung des Mieters (§ 558b BGB)
Der Mieter hat bis zum Ablauf des **zweiten Kalendermonats nach Zugang** Zeit zur
Zustimmung. Stimmt er nicht zu, kann der Vermieter binnen weiterer drei Monate auf
Zustimmung klagen.

## Ausschluss
§ 558 gilt nicht bei vereinbarter Staffelmiete (§ 557a) oder Indexmiete (§ 557b) und nicht
bei einer Erhöhung, die eine getroffene Vereinbarung überschreiten würde.$t$,
