insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$09-modernisierung-555b-559#0$t$,
  $t$09-modernisierung-555b-559$t$,
  $t$Modernisierung und Modernisierungsumlage (§§ 555b–555d, 559 BGB)$t$,
  $t$Duldungspflicht (§ 555b, § 555d BGB)$t$,
  '{"modernisierung","duldungspflicht","modernisierungsumlage","kappung"}',
  $t$Der Mieter hat energetische Modernisierungen, Maßnahmen zur Einsparung von Wasser, zur
nachhaltigen Verbrauchssenkung, zur Verbesserung des Gebrauchswerts oder der allgemeinen
Wohnverhältnisse sowie die Schaffung neuen Wohnraums zu **dulden** (§ 555b BGB), es sei
denn, die Maßnahme bedeutet eine nicht zu rechtfertigende **Härte** (§ 555d Abs. 2 BGB).

## Ankündigung (§ 555c BGB)
Die Modernisierung ist dem Mieter **spätestens drei Monate vor Beginn in Textform**
anzukündigen, mit Angabe von Art, Umfang, Beginn, voraussichtlicher Dauer und der zu
erwartenden Mieterhöhung sowie der künftigen Betriebskosten.$t$,
