insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$11-kleinreparaturen#2$t$,
  $t$11-kleinreparaturen$t$,
  $t$Kleinreparaturklausel (Bagatellschäden)$t$,
  $t$Musterformulierung$t$,
  '{"kleinreparaturen","bagatellschaeden","einzelobergrenze","jahresobergrenze"}',
  $t$„Der Mieter trägt die Kosten kleiner Instandhaltungen an Installationsgegenständen für
Elektrizität, Wasser und Gas, Heiz- und Kocheinrichtungen, Fenster- und Türverschlüssen
sowie Verschlussvorrichtungen von Fensterläden, soweit diese Teile seinem direkten Zugriff
unterliegen. Die Kostentragung ist auf **100 EUR je Einzelfall** und auf **8 % der
Jahresnettokaltmiete pro Kalenderjahr** begrenzt. Übersteigen die Kosten einer Maßnahme
100 EUR, trägt sie vollständig der Vermieter."$t$,
