insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$12-ordentliche-kuendigung-vermieter-573#0$t$,
  $t$12-ordentliche-kuendigung-vermieter-573$t$,
  $t$Ordentliche Kündigung durch den Vermieter (§ 573 BGB)$t$,
  $t$Berechtigtes Interesse erforderlich$t$,
  '{"kuendigung","vermieter","berechtigtes-interesse","eigenbedarf","begruendung"}',
  $t$Der Vermieter kann ein unbefristetes Wohnraummietverhältnis **nur kündigen, wenn er ein
berechtigtes Interesse** an der Beendigung hat (§ 573 Abs. 1 BGB). Eine Kündigung „zur
Mietrenditeoptimierung" oder ohne Grund ist ausgeschlossen. Regelbeispiele (§ 573 Abs. 2
BGB):

1. **Erhebliche schuldhafte Vertragsverletzung** des Mieters (z. B. wiederholt
   unpünktliche Mietzahlung, nachhaltige Störung des Hausfriedens).
2. **Eigenbedarf:** Der Vermieter benötigt die Wohnung für sich, Familienangehörige oder
   Angehörige seines Haushalts.
3. **Hinderung angemessener wirtschaftlicher Verwertung** des Grundstücks mit
   erheblichen Nachteilen (nicht: Verkauf zu höherem Preis in unvermietetem Zustand).$t$,
