insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$12-ordentliche-kuendigung-vermieter-573#2$t$,
  $t$12-ordentliche-kuendigung-vermieter-573$t$,
  $t$Ordentliche Kündigung durch den Vermieter (§ 573 BGB)$t$,
  $t$Musterformulierung$t$,
  '{"kuendigung","vermieter","berechtigtes-interesse","eigenbedarf","begruendung"}',
  $t$„Der Vermieter kann das Mietverhältnis nur bei berechtigtem Interesse im Sinne des § 573
BGB kündigen. Die Kündigung bedarf der Schriftform und der Angabe der Kündigungsgründe.
Auf das Widerspruchsrecht des Mieters nach §§ 574 ff. BGB wird hingewiesen."$t$,
