insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$15-eigenbedarf-573-2-2#2$t$,
  $t$15-eigenbedarf-573-2-2$t$,
  $t$Eigenbedarfskündigung (§ 573 Abs. 2 Nr. 2 BGB)$t$,
  $t$Härtewiderspruch$t$,
  '{"eigenbedarf","kuendigung","beguenstigte-personen","vortaeuschung"}',
  $t$Der Mieter kann nach §§ 574 ff. BGB widersprechen (Alter, Krankheit, kein zumutbarer
Ersatzwohnraum). Das Gericht wägt die Interessen ab und kann das Mietverhältnis befristet
oder unbefristet fortsetzen.

## Musterformulierung
„Eine Kündigung wegen Eigenbedarfs setzt voraus, dass der Vermieter die Wohnung für sich,
einen Familienangehörigen oder einen Angehörigen seines Haushalts benötigt und dies im
Kündigungsschreiben konkret darlegt (§ 573 Abs. 2 Nr. 2, Abs. 3 BGB)."$t$,
