insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$19-uebergabe-ruckgabe-protokoll#2$t$,
  $t$19-uebergabe-ruckgabe-protokoll$t$,
  $t$Wohnungsübergabe, Übergabeprotokoll und Rückgabe (§ 546 BGB)$t$,
  $t$Musterformulierung$t$,
  '{"uebergabe","uebergabeprotokoll","rueckgabe","zaehlerstaende","kaution"}',
  $t$„Über den Zustand der Wohnung bei Übergabe und bei Rückgabe wird jeweils ein von beiden
Parteien unterzeichnetes Protokoll einschließlich der Zählerstände erstellt. Der Mieter
gibt die Wohnung besenrein und mit allen Schlüsseln zurück (§ 546 BGB). Für normale
Abnutzung durch vertragsgemäßen Gebrauch haftet der Mieter nicht (§ 538 BGB)."$t$,
