insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$20-umwandlung-577-577a#1$t$,
  $t$20-umwandlung-577-577a$t$,
  $t$Umwandlung in Wohnungseigentum — Vorkaufsrecht und Kündigungssperrfrist (§§ 577, 577a BGB)$t$,
  $t$Bedeutung für die Vertragsgestaltung$t$,
  '{"umwandlung","wohnungseigentum","vorkaufsrecht","kuendigungssperrfrist"}',
  $t$Bei laufenden Mietverhältnissen in Eigentumswohnungen, die aus einer Umwandlung
hervorgegangen sind, ist im Vertrag auf die Sperrfrist hinzuweisen; sie kann nicht zum
Nachteil des Mieters verkürzt werden (§ 577a Abs. 3 BGB).

## Musterformulierung
„Wird an der Wohnung nach Überlassung Wohnungseigentum begründet und veräußert, gelten
zugunsten des Mieters das Vorkaufsrecht nach § 577 BGB und die Kündigungssperrfrist nach
§ 577a BGB (drei Jahre, in Gebieten mit angespanntem Wohnungsmarkt bis zu zehn Jahre)."$t$,
