insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$22-standard-wohnraummietvertrag-vorlage#2$t$,
  $t$22-standard-wohnraummietvertrag-vorlage$t$,
  $t$Standard-Wohnraummietvertrag — annotierte Vorlage$t$,
  $t$§ 5 Kaution$t$,
  '{"vorlage","muster","wohnraummietvertrag","template","aufbau"}',
  $t$„Der Mieter leistet eine Barkaution in Höhe von [max. drei Nettokaltmieten] EUR. Sie kann
in drei gleichen Monatsraten gezahlt werden; die erste Rate ist zu Mietbeginn fällig. Der
Vermieter legt die Kaution getrennt von seinem Vermögen zum für Spareinlagen mit
dreimonatiger Kündigungsfrist üblichen Zinssatz an; die Erträge stehen dem Mieter zu
(§ 551 BGB). Die Rückzahlung erfolgt nach Rückgabe der Wohnung binnen angemessener Frist,
abzüglich noch offener Ansprüche."$t$,
