insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$22-standard-wohnraummietvertrag-vorlage#3$t$,
  $t$22-standard-wohnraummietvertrag-vorlage$t$,
  $t$Standard-Wohnraummietvertrag — annotierte Vorlage$t$,
  $t$§ 6 Schönheitsreparaturen$t$,
  '{"vorlage","muster","wohnraummietvertrag","template","aufbau"}',
  $t$„Die Wohnung wird renoviert übergeben. Der Mieter führt die Schönheitsreparaturen
(Tapezieren, Streichen von Wänden und Decken, Streichen von Heizkörpern, Innentüren sowie
Fenstern und Türen von innen) fachgerecht aus, sobald der Zustand der Wohnung dies
erfordert. Als Richtwerte gelten — abhängig vom tatsächlichen Zustand — im Allgemeinen:
Küche und Bad alle drei Jahre, Wohn- und Schlafräume alle fünf Jahre, Nebenräume alle
sieben Jahre. Starre Fristen sowie eine anteilige Kostenabgeltung bei vorzeitigem Auszug
werden nicht vereinbart. Bei Rückgabe erfolgt der Anstrich in hellen, neutralen Farbtönen."$t$,
