insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$22-standard-wohnraummietvertrag-vorlage#5$t$,
  $t$22-standard-wohnraummietvertrag-vorlage$t$,
  $t$Standard-Wohnraummietvertrag — annotierte Vorlage$t$,
  $t$§ 9 Instandhaltung und Modernisierung$t$,
  '{"vorlage","muster","wohnraummietvertrag","template","aufbau"}',
  $t$„Der Vermieter erhält die Mietsache im vertragsgemäßen Zustand (§ 535 BGB). Der Mieter
zeigt Mängel unverzüglich in Textform an (§ 536c BGB); die gesetzlichen Minderungsrechte
bleiben unberührt. Modernisierungen kündigt der Vermieter spätestens drei Monate vorher in
Textform an (§ 555c BGB); Mieterhöhungen nach § 559 BGB sind auf 8 % der Kosten und die
Kappungsgrenze des § 559 Abs. 3a BGB begrenzt."$t$,
