insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$23-mietvertrag-checkliste#1$t$,
  $t$23-mietvertrag-checkliste$t$,
  $t$Checkliste — Pflicht- und Empfehlungsinhalte eines Wohnraummietvertrags$t$,
  $t$Dringend empfohlen$t$,
  '{"checkliste","pflichtangaben","pruefung","vollstaendigkeit"}',
  $t$- **Kaution** höchstens drei Nettokaltmieten, Ratenzahlung, getrennte Anlage (§ 551 BGB).
- **Schönheitsreparaturen** nur bei renovierter Übergabe, weiche Fristen, keine
  Quotenklausel.
- **Kleinreparaturen** mit Einzel- und Jahresobergrenze.
- **Untervermietung, Tierhaltung, Nutzung** BGH-konform geregelt.
- **Kündigung**: Verweis auf §§ 573, 573c BGB; kein längeres Kündigungsrecht zulasten des
  Mieters.
- **Übergabeprotokoll** mit Zählerständen als Anlage.
- **Hausordnung** als Anlage, auf Ordnung und Sicherheit beschränkt.
- **Salvatorische Klausel** mit Rückfall auf das Gesetz.
- **Textformklausel** für Änderungen.$t$,
