insert into rag_chunks (id, doc_id, doc_title, heading, tags, text, embedding) values (
  $t$23-mietvertrag-checkliste#2$t$,
  $t$23-mietvertrag-checkliste$t$,
  $t$Checkliste — Pflicht- und Empfehlungsinhalte eines Wohnraummietvertrags$t$,
  $t$Unzulässig — nicht aufnehmen$t$,
  '{"checkliste","pflichtangaben","pruefung","vollstaendigkeit"}',
  $t$- Ausschluss oder Erschwerung der Mietminderung (§ 536 Abs. 4 BGB).
- Kaution über drei Nettokaltmieten oder fällig vor Übergabe.
- Starre Schönheitsreparatur-Fristen, Endrenovierungs- oder Quotenabgeltungsklausel.
- Kleinreparaturklausel ohne Höchstbeträge oder mit anteiliger Beteiligung.
- Generelles Tierhaltungsverbot; generelles Untervermietungsverbot ohne § 553-Vorbehalt.
- Für den Mieter längere Kündigungsfristen als drei Monate.
- Vertragsstrafen und pauschale Schadensersatzbeträge zulasten des Mieters in
  Formularverträgen.
- Platzhalter wie „[EINFÜGEN]" oder unbezifferte Beträge im finalen Vertrag.$t$,
